            //
            aOrbiterE = (((aWandererH + RotL64(aPrevious, 29U)) + RotL64(aCarry, 47U)) + 0x7C06D577D91431A0ULL) + aTwistOrbiterAssignSaltE[((aIndex + 25U)) & S_SALT1];
            aOrbiterB = (aWandererF + RotL64(aCross, 39U)) + 0xE978DEFBC5EA653DULL;
            aOrbiterF = ((aWandererB + RotL64(aScatter, 5U)) + RotL64(aCarry, 19U)) + 0x6EB16B318F059922ULL;
            aOrbiterC = ((aWandererK + RotL64(aIngress, 14U)) + 0xA0982DB8C7B42AE9ULL) + aTwistOrbiterAssignSaltC[((aIndex + 3U)) & S_SALT1];
            aOrbiterD = ((aWandererJ + RotL64(aCross, 47U)) + RotL64(aCarry, 35U)) + 0x2C5F57BE042E5518ULL;
