            aOrbiterJ = RotL64((aOrbiterJ * 0x44FCC98744A5AC0DULL), 51U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0xBB6E0299F45ACA28ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterK) ^ 0x5CF12C0929FBED0DULL;
