            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterC) + 0x898C182EDE1A2FB9ULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterJ) ^ 0x5594EE037A8147EDULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x8C260FB7BB32333DULL), 3U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterF) + 0xA2DE823FAC73B446ULL;
