            //
            aWandererF = aWandererF ^ (((RotL64(aIngress, 21U) + RotL64(aOrbiterF, 11U)) + aOrbiterE) + aTwistWandererUpdateSaltE[((aIndex + 15U)) & S_SALT1]);
