            aWandererB = aWandererB ^ ((RotL64(aPrevious, 30U) + RotL64(aOrbiterB, 3U)) + aOrbiterC);
            aWandererH = aWandererH + ((((RotL64(aScatter, 51U) + aOrbiterJ) + RotL64(aOrbiterE, 29U)) + RotL64(aCarry, 23U)) + aTwistWandererUpdateSaltD[((aIndex + 22U)) & S_SALT1]);
