            //
            aOrbiterJ = ((aWandererI + RotL64(aIngress, 57U)) + RotL64(aCarry, 41U)) + 0xB9425DCC7E17E8BBULL;
            aOrbiterB = (aWandererD + RotL64(aCross, 14U)) + 0x31EE15205AE514D9ULL;
            aOrbiterA = (aWandererJ + RotL64(aScatter, 5U)) + 0x8CDA3C5E1B50A842ULL;
            aOrbiterH = ((aWandererE + RotL64(aPrevious, 51U)) + RotL64(aCarry, 57U)) + 0x4620BC9E85237E69ULL;
            aOrbiterF = ((aWandererH + RotL64(aScatter, 41U)) + 0x5097605D8AB25AB6ULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterE = ((aWandererK + RotL64(aIngress, 35U)) + 0x5B978FE0D36B38F5ULL) + aTwistOrbiterAssignSaltD[((aIndex + 10U)) & S_SALT1];
            aOrbiterD = ((aWandererC + RotL64(aCross, 29U)) + RotL64(aCarry, 27U)) + 0x9CC2862CC3F9FDF9ULL;
            //
