            aScatter = (RotL64(aIngress, 57U) ^ RotL64(aCross, 10U)) ^ (RotL64(aPrevious, 27U) + RotL64(aCarry, 43U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterC = ((aWandererJ + RotL64(aPrevious, 35U)) + 0x59DF1FBA39AEEB1CULL) + aKeyRotateOrbiterAssignSaltE[((aIndex + 25U)) & S_SALT1];
            aOrbiterH = (aWandererB + RotL64(aScatter, 42U)) + 0x769751E0F1F9B541ULL;
            aOrbiterI = (aWandererC + RotL64(aIngress, 29U)) + 0x3F6F1A287944A0DDULL;
            aOrbiterJ = ((aWandererI + RotL64(aCross, 51U)) + RotL64(aCarry, 27U)) + 0x4D3A0EEC9C351529ULL;
            aOrbiterD = (((aWandererD + RotL64(aIngress, 53U)) + RotL64(aCarry, 41U)) + 0xA42DC38F6AAD6649ULL) + aKeyRotateOrbiterAssignSaltD[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterK = (aWandererF + RotL64(aScatter, 21U)) + 0x5685EF42BC7D66DBULL;
            aOrbiterE = ((aWandererK + RotL64(aPrevious, 5U)) + RotL64(aCarry, 19U)) + 0x58AC37B47EB85846ULL;
            aOrbiterF = (aWandererA + RotL64(aCross, 11U)) + 0x05AD542672A88A1FULL;
            aOrbiterB = (aWandererH + RotL64(aIngress, 57U)) + 0x637A686FCA085CC4ULL;
            aOrbiterG = (aWandererG + RotL64(aCross, 37U)) + 0xF6F12204A6794AB6ULL;
            aOrbiterA = (aWandererE + RotL64(aScatter, 46U)) + 0x74CE87EE83D1B4A3ULL;
            //
            aOrbiterC = (aOrbiterC + aOrbiterH) + 0x56469C170A8E7BDEULL;
