            //
            aOrbiterE = (aOrbiterE + aOrbiterF) + 0xB14F18A8F69E20DCULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterE) ^ 0xF5DA4DB57BE57A6DULL;
            aOrbiterH = RotL64((aOrbiterH * 0x037407D707E5D063ULL), 37U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x6068B1A39712ABAFULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterB) ^ 0x5ECAB8D4D5FCCDBEULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 12U)) & S_SALT1];
