            aOrbiterE = ((aOrbiterE + aOrbiterI) + 0x28C2493E6E4396F4ULL) + aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterE) ^ 0x44871CE2699C914EULL;
            aOrbiterG = RotL64((aOrbiterG * 0x8A36BAA205785E53ULL), 3U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterD) + 0x18DB887580D4BB10ULL) + aKeyRotateOrbiterUpdateSaltA[((aIndex + 13U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0x5BDCC36504467902ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x738EC3A4C892B34FULL), 11U);
