            aOrbiterF = ((aOrbiterF + aOrbiterA) + 0x9FAF9D5B67B14423ULL) + aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0xE2092AF81196F930ULL;
