            aOrbiterE = ((aOrbiterE + aOrbiterF) + 0xC0E55CDF5B8DA0B4ULL) + aKeySpawnOrbiterUpdateSaltE[((aIndex + 22U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0x83E864B2AAB4094BULL;
